const endpoints = await this.helpers.httpRequest({method: 'GET',
  url: 'http://127.0.0.1:8494/api/v1/endpoints/statuses', json: true, timeout: 20000});
if (!Array.isArray(endpoints) || endpoints.length === 0) throw new Error('Gatus returned no service probes');
const out = [];
for (const endpoint of endpoints) {
  const results = [...(endpoint.results ?? [])].sort((a,b) => String(a.timestamp ?? '').localeCompare(String(b.timestamp ?? '')));
  const failures = results.slice(-3);
  const successes = results.slice(-2);
  const down = failures.length === 3 && failures.every(r => r.success === false);
  const up = successes.length === 2 && successes.every(r => r.success === true);
  if (!down && !up) continue;
  out.push({json: {source: 'services', severity: ['n8n', 'ntfy', 'prometheus', 'grafana', 'adguard'].includes(endpoint.name) ? 'critical' : 'warning',
    title: `${endpoint.name} ${down ? 'is down' : 'recovered'}`,
    message: down ? 'Three consecutive probes failed. Check the service and the status page.' : 'The service is responding again.',
    fingerprint: `service:${endpoint.key ?? endpoint.name}`, resolved: up,
    url: 'https://status.hugo-berendi.de',
  }});
}
return out;
